package enrich

import (
	"context"
	"fmt"
	"time"

	"github.com/mellifera/mellifera/internal/module"
	commonv1 "github.com/mellifera/mellifera/proto/mellifera/common/v1"
	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// outcomeKind is the result of running one source's chain. Unexported.
type outcomeKind int

const (
	outcomeSucceeded   outcomeKind = iota // chain ran + namespace written
	outcomeFailed                         // chain ran but an RPC errored or namespace was violated
	outcomeUnavailable                    // plugin not loaded / not resolvable
	outcomeSkipped                        // disabled, or Match returned applies=false
)

// sourceResult is runSource's output: the source's contribution (namespace +
// provenance/_view entries) on success, or the failure detail otherwise. The
// document is NOT mutated here — Enrich commits the contribution (INV per-source
// isolation, R-4: a violation mid-chain leaves the pre-source document intact).
type sourceResult struct {
	kind       outcomeKind
	pluginID   string
	namespace  map[string]any            // sources.<plugin_id> (succeeded only)
	provenance map[string]map[string]any // _provenance.<field> entries (succeeded only)
	view       map[string]map[string]any // _view.<field> entries (succeeded only)
	warnings   []string
	errMsg     string
	startedAt  string
	finishedAt string
}

// runSource drives the full 4-RPC chain for one metadata_source binding:
// Match -> BuildRequest -> Convert -> Merge, serial (D8). The fetch between
// BuildRequest and Convert is a no-op stub (empty raw_response) in Phase A — all
// 4 RPCs are still invoked so Phase B swaps in a real fetcher with no signature
// change (INV-4rpc-contract). On any per-source failure the chain soft-fails
// (AC-6); only a cancelled context is a hard failure (handled by Enrich).
func runSource(ctx context.Context, resolve metadataResolver, src module.MetadataSourceBinding, mod module.Module, base *scannerv1.IdentifyResult) sourceResult {
	start := stamp()
	if !src.Enabled {
		return sourceResult{kind: outcomeSkipped, pluginID: src.PluginID, startedAt: start, finishedAt: stamp()}
	}
	md, err := resolve(src.PluginID, src.CapabilityID)
	if err != nil {
		return skipOutcome(src, start, fmt.Sprintf("unavailable: %v", err))
	}
	matchRes, err := md.Match(ctx, &metadatav1.MatchRequest{Item: base, ModuleType: mod.MediaType})
	if err != nil {
		return failOutcome(src, start, "match", err)
	}
	if !matchRes.GetApplies() { // B3: not an error — record a skipped stage, continue
		return sourceResult{kind: outcomeSkipped, pluginID: src.PluginID, startedAt: start, finishedAt: stamp()}
	}
	if _, err := md.BuildRequest(ctx, &metadatav1.BuildRequestRequest{
		Query: matchRes.GetQuery(), ModuleType: mod.MediaType, Auth: &commonv1.AuthContext{},
	}); err != nil { // BuildRequest receives an EMPTY AuthContext in Phase A (D-7); spec is ignored (fetch stubbed)
		return failOutcome(src, start, "build_request", err)
	}
	conv, err := md.Convert(ctx, &metadatav1.ConvertRequest{Query: matchRes.GetQuery(), ModuleType: mod.MediaType})
	if err != nil {
		return failOutcome(src, start, "convert", err)
	}
	if cerr := conv.GetError(); cerr != nil {
		return failOutcome(src, start, "convert", fmt.Errorf("%s: %s", cerr.GetCode(), cerr.GetMessage()))
	}
	merged, err := md.Merge(ctx, &metadatav1.MergeRequest{
		Incoming:   conv.GetMetadata(),
		Document:   &commonv1.MediaDocument{}, // empty: plugin writes only its namespace; core validates + stamps (§3.2 L2)
		ModuleType: mod.MediaType,
		PluginId:   src.PluginID,
		Policy:     &metadatav1.MergePolicy{},
	})
	if err != nil {
		return failOutcome(src, start, "merge", err)
	}
	namespace, verr := validateNamespace(merged.GetDocument(), src.PluginID)
	if verr != nil { // B6: namespace violation -> reject + revert (doc untouched) + failed stage + soft-fail
		return failOutcome(src, start, "merge", verr)
	}
	prov, view := buildProvenanceView(src.PluginID, namespace, conv.GetProvenance(), matchRes.GetConfidence())
	return sourceResult{
		kind: outcomeSucceeded, pluginID: src.PluginID,
		namespace: namespace, provenance: prov, view: view,
		startedAt: start, finishedAt: stamp(),
	}
}

// validateNamespace enforces the architecture §3.3 invariant: the plugin may
// write ONLY sources.<its_own_plugin_id>. A foreign top-level key or a foreign
// source namespace is a violation (rejected + reverted by the caller). The
// plugin's own namespace is unconstrained (§3.3 #1). Returns the plugin's
// namespace contribution (nil if it wrote nothing).
func validateNamespace(doc *commonv1.MediaDocument, pluginID string) (map[string]any, error) {
	if doc == nil || doc.GetData() == nil {
		return nil, nil
	}
	data := doc.GetData().AsMap()
	for k := range data {
		if k != "sources" {
			return nil, fmt.Errorf("plugin wrote outside sources namespace: %q", k)
		}
	}
	sources, _ := data["sources"].(map[string]any)
	for k := range sources {
		if k != pluginID {
			return nil, fmt.Errorf("plugin wrote a foreign source namespace: sources.%s", k)
		}
	}
	namespace, _ := sources[pluginID].(map[string]any)
	return namespace, nil
}

// stamp returns an RFC3339 UTC timestamp from the package clock (test-overridable
// for deterministic _stages/_provenance timestamps).
func stamp() string {
	return now().UTC().Format(time.RFC3339)
}

func failOutcome(src module.MetadataSourceBinding, start, stage string, err error) sourceResult {
	msg := fmt.Sprintf("%s: %v", stage, err)
	return sourceResult{
		kind: outcomeFailed, pluginID: src.PluginID, errMsg: msg,
		warnings:  []string{fmt.Sprintf("source %q %s", src.PluginID, msg)},
		startedAt: start, finishedAt: stamp(),
	}
}

func skipOutcome(src module.MetadataSourceBinding, start, reason string) sourceResult {
	return sourceResult{
		kind: outcomeUnavailable, pluginID: src.PluginID,
		warnings:  []string{fmt.Sprintf("source %q skipped: %s", src.PluginID, reason)},
		startedAt: start, finishedAt: stamp(),
	}
}
